class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.

    Static routes win over dynamic routes regardless of registration order.
    Dynamic routes use <name> syntax for parameterized segments.
    """

    def __init__(self):
        self._static_routes = []
        self._dynamic_routes = []

    def add(self, path, handler):
        segments = path.split("/")
        is_dynamic = any(seg.startswith("<") and seg.endswith(">") for seg in segments)
        if is_dynamic:
            self._dynamic_routes.append((path, handler))
        else:
            self._static_routes.append((path, handler))

    def resolve(self, path):
        # First, check static routes in registration order
        for route, handler in self._static_routes:
            if route == path:
                return handler, {}

        # Then, check dynamic routes in registration order
        path_segments = path.split("/")
        for route, handler in self._dynamic_routes:
            route_segments = route.split("/")
            if len(path_segments) != len(route_segments):
                continue
            params = {}
            match = True
            for seg, pattern_seg in zip(path_segments, route_segments):
                if pattern_seg.startswith("<") and pattern_seg.endswith(">"):
                    param_name = pattern_seg[1:-1]
                    if seg == "":
                        match = False
                        break
                    params[param_name] = seg
                else:
                    if seg != pattern_seg:
                        match = False
                        break
            if match:
                return handler, params

        return None, {}

