class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.

    Static routes (no <name> segments) always win over dynamic routes that
    also match, regardless of registration order. Within each category,
    the first registered route wins.
    """

    def __init__(self):
        self._routes = []

    def add(self, path, handler):
        is_dynamic = '<' in path
        self._routes.append((path, handler, is_dynamic))

    def resolve(self, path):
        # First pass: check static routes (first registered wins)
        for route, handler, is_dynamic in self._routes:
            if not is_dynamic and route == path:
                return handler, {}

        # Second pass: check dynamic routes (first registered wins)
        for route, handler, is_dynamic in self._routes:
            if is_dynamic:
                params = self._match_dynamic(route, path)
                if params is not None:
                    return handler, params

        return None, {}

    def _match_dynamic(self, route, path):
        """Match a dynamic route against a path and return captured params, or None."""
        route_segments = route.split('/')
        path_segments = path.split('/')

        if len(route_segments) != len(path_segments):
            return None

        params = {}
        for rs, ps in zip(route_segments, path_segments):
            if rs.startswith('<') and rs.endswith('>'):
                # Parameter segment: must not match an empty string
                if not ps:
                    return None
                name = rs[1:-1]
                params[name] = ps
            else:
                # Static segment: must match exactly
                if rs != ps:
                    return None

        return params

