class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.

    Supports parameterized path segments written as ``<name>``, e.g.
    ``/jobs/<job_id>/runs/<run_id>``.  A static route always wins over a
    dynamic route that also matches, regardless of registration order.
    """

    def __init__(self):
        self._routes = []
        self._static_routes = []
        self._dynamic_routes = []

    def add(self, path, handler):
        self._routes.append((path, handler))
        if "<" in path:
            self._dynamic_routes.append((path, handler))
        else:
            self._static_routes.append((path, handler))

    def resolve(self, path):
        # Static routes always win over dynamic routes.
        for route, handler in self._static_routes:
            if route == path:
                return handler, {}

        # Then try dynamic routes in registration order.
        for route, handler in self._dynamic_routes:
            params = self._match_dynamic(route, path)
            if params is not None:
                return handler, params

        return None, {}

    @staticmethod
    def _match_dynamic(route, path):
        route_segments = route.split("/")
        path_segments = path.split("/")

        if len(route_segments) != len(path_segments):
            return None

        params = {}
        for route_seg, path_seg in zip(route_segments, path_segments):
            if route_seg.startswith("<") and route_seg.endswith(">"):
                # Empty segments must not satisfy a parameter.
                if not path_seg:
                    return None
                name = route_seg[1:-1]
                params[name] = path_seg
            else:
                if route_seg != path_seg:
                    return None

        return params
